CSS=r'''@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#eaeff4;--muted:#92a0b2;--bg:#080c11;--panel:#141c26;--line:#2a3645;--accent:#afff82;--accent2:#7ba7ff;--good:#8cf5be;--bad:#ff8291;font-family:'DM Sans',system-ui,sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);min-height:100vh}button,input,textarea,select{font:inherit}button{cursor:pointer;background:var(--accent);color:#101913;border:0;padding:11px 16px;border-radius:9px;font-weight:750}button:hover{filter:brightness(1.1)}button:disabled{opacity:.45;cursor:not-allowed}.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}.secondary{background:var(--panel);color:var(--ink);border:1px solid var(--line)}a{color:inherit;text-decoration:none}input,select,textarea{background:#0d141d;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:10px;max-width:100%;min-width:0}textarea{width:100%;min-height:110px;resize:vertical}label{font-size:.83rem;color:var(--muted);display:grid;gap:6px}h1,h2,h3{font-family:'Space Grotesk',sans-serif;line-height:1.1;letter-spacing:-.04em;margin:0}h1{font-size:clamp(2rem,5vw,4.5rem)}h2{font-size:clamp(1.2rem,2vw,1.8rem)}p{line-height:1.55;color:var(--muted)}small{color:var(--muted)}.top{position:sticky;z-index:20;top:0;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px clamp(16px,4vw,58px);background:#080c11d9;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.brand{font-family:'DM Mono',monospace;font-weight:700;font-size:.88rem;letter-spacing:.09em;color:var(--accent)}.back{font-size:.85rem;color:#b6c5d3}.container{width:min(1220px,94%);margin:auto;padding:40px 0 110px}.eyebrow{font:600 .74rem 'DM Mono',monospace;letter-spacing:.16em;color:var(--accent);text-transform:uppercase}.hero{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:5px 0 32px}.hero p{max-width:690px}.tag{padding:6px 10px;border:1px solid var(--line);border-radius:100px;color:var(--muted);font-size:.72rem}.panel,.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px}.panel h2,.card h2{margin-bottom:14px}.stack{display:grid;gap:14px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:16px}.cols3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.controls{display:flex;gap:9px;flex-wrap:wrap;align-items:end}.controls>*{flex-shrink:0}.kpi{background:#0c141d;border:1px solid var(--line);padding:15px;border-radius:12px}.kpi strong{display:block;font-size:1.4rem;font-family:'DM Mono',monospace;margin-top:4px}.kpi span{font-size:.75rem;color:var(--muted)}.mono,pre,code{font-family:'DM Mono',monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0a111a;padding:16px;border-radius:10px;border:1px solid var(--line);color:#a4e2cd;max-height:330px;overflow:auto;font-size:.78rem}.status{font:.78rem 'DM Mono',monospace;color:var(--good);min-height:1.2rem}.muted{color:var(--muted)}.hint{font-size:.77rem;color:var(--muted)}.warn{color:var(--bad)}canvas{max-width:100%;background:#080f16;border:1px solid var(--line);border-radius:12px}.table-wrap{overflow:auto;max-height:380px}table{border-collapse:collapse;width:100%;font-size:.8rem}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line)}th{color:var(--muted)}hr{border:0;border-top:1px solid var(--line);margin:20px 0}.footer{padding:40px 0;text-align:center;font-size:.76rem;color:var(--muted)}.special{font-family:'DM Mono',monospace}.chip{display:inline-block;border:1px solid var(--line);border-radius:5px;padding:4px 7px;font-size:.7rem;color:var(--muted)}
body.chess{--accent:#eed6b0;--bg:#151516;--panel:#242626;--line:#414240}body.pac{--accent:#ffe73a;--bg:#090627;--panel:#16114a;--line:#473f85;font-family:'DM Mono',monospace}body.market{--accent:#32e6b5;--bg:#061416;--panel:#0d2527;--line:#215054}body.vision{--accent:#00e3f7;--bg:#06131e;--panel:#0e2635;--line:#244c65}body.chain{--accent:#ffb273;--bg:#170d0c;--panel:#291a18;--line:#594038}body.threat{--accent:#ff6185;--bg:#0d0b12;--panel:#1d1825;--line:#473b57}body.neural{--accent:#a891ff;--bg:#100c20;--panel:#201936;--line:#45365f}body.growth{--accent:#e0ff73;--bg:#161c13;--panel:#273024;--line:#515e45}body.cloud{--accent:#80c6ff;--bg:#071222;--panel:#172538;--line:#324965}body.climate{--accent:#87d6ff;--bg:#07171f;--panel:#152c35;--line:#365461}
body.pac h1,body.pac h2{letter-spacing:.01em;text-shadow:0 0 22px #ffe73a6a}body.market .panel,body.threat .panel{border-radius:4px}body.growth .panel{border-radius:26px}body.chess .panel{box-shadow:0 15px 60px #0005}body.chain .panel{border-left:3px solid #ffb273}
@media(max-width:850px){.cols,.cols3{grid-template-columns:1fr}.hero{display:block}.top{padding:12px 16px}.container{padding-top:20px}.panel{padding:16px}}'''
(ROOT/'styles.css').write_text(CSS)
