BODIES={
'chess-engine':'''<div class="cols" style="grid-template-columns:minmax(0,570px) minmax(260px,1fr)"><div class="panel"><div class="controls" style="margin-bottom:12px"><button id="new">New game</button><button class="secondary" id="undo">Undo move</button><label>Opponent<select id="opponent"><option value="ai">Minimax AI (black)</option><option value="human">Local two-player</option></select></label></div><div id="chessBoard" class="board-chess" role="grid" aria-label="Chess board"></div><p id="turn" class="status" aria-live="polite"></p></div><div class="stack"><div class="panel"><h2>Move history</h2><div id="moves" class="mono" style="max-height:400px;overflow:auto"></div></div><div class="panel"><h2>Engine features</h2><p>Legal move filtering · self-check prevention · castling · en passant · promotion · reversible state · minimax with material and mobility evaluation.</p><p class="hint">Select a piece, then a destination. Promotion automatically chooses a queen. The AI searches 2 plies.</p></div></div></div><style>.board-chess{width:min(100%,540px);display:grid;grid-template-columns:repeat(8,1fr);aspect-ratio:1;overflow:hidden;border:8px solid #8b6b49;border-radius:4px;margin:auto}.sq{border:0;border-radius:0;display:grid;place-items:center;font-size:clamp(24px,4.5vw,47px);padding:0;position:relative;aspect-ratio:1;font-family:Arial}.sq.light{background:#eddcbb}.sq.dark{background:#8e977d}.sq.sel{outline:4px solid #ffdb66;outline-offset:-5px}.sq.legal::after{content:'';position:absolute;width:20%;aspect-ratio:1;background:#0d645e99;border-radius:50%}.sq.check{background:#ff6a74}.sq:focus-visible{z-index:2;outline:4px solid #1468df}</style>''',
'pac-maze':'''<div class="cols"><div class="panel" style="text-align:center"><canvas id="maze" width="560" height="560" style="image-rendering:pixelated;max-height:70vh"></canvas><p class="hint">Arrow keys / WASD, or tap directional controls. Ghosts use BFS shortest-path pursuit.</p><div class="controls" style="justify-content:center"><button data-d="up">▲</button><button data-d="left">◀</button><button data-d="down">▼</button><button data-d="right">▶</button></div></div><div class="stack"><div class="cols3"><div class="kpi"><span>SCORE</span><strong id="score">0</strong></div><div class="kpi"><span>LIVES</span><strong id="lives">3</strong></div><div class="kpi"><span>LEVEL</span><strong id="level">1</strong></div></div><div class="panel"><h2>THE MAZE</h2><p>A real-time game loop with deterministic tile collision, power-pellet timers, state transitions and adversaries using graph search.</p><button id="restart">Restart run</button><p id="message" class="status"></p></div></div></div>''',
'market-lab':'''<div class="stack"><div class="panel"><div class="controls"><label>Price CSV<input type="file" id="csv" accept=".csv,text/csv"></label><label>Short EMA<input id="fast" type="number" value="8" min="2" max="100" style="width:85px"></label><label>Long EMA<input id="slow" type="number" value="21" min="3" max="200" style="width:85px"></label><label>Fee per trade (%)<input id="fee" type="number" value="0.1" step="0.05" style="width:95px"></label><button id="run">Backtest</button></div><p class="hint">Default uses a deterministic synthetic example—not live exchange data. Upload a real CSV with Date,Close columns to evaluate historical data. Long-only; next-bar execution, fees and max drawdown calculated.</p></div><div class="cols3"><div class="kpi"><span>Strategy return</span><strong id="ret">—</strong></div><div class="kpi"><span>Buy & hold</span><strong id="hold">—</strong></div><div class="kpi"><span>Max drawdown</span><strong id="dd">—</strong></div></div><div class="panel"><h2>Equity & asset price</h2><canvas id="equity" width="1100" height="370"></canvas></div><div class="panel"><h2>Execution log</h2><div id="trades" class="table-wrap"></div></div></div>''',
'vision-lab':'''<div class="cols"><div class="panel"><div class="controls" style="margin-bottom:15px"><button id="start">Enable camera</button><button id="stop" class="secondary">Stop</button><button id="capture" class="secondary">Save snapshot locally</button></div><div style="position:relative;background:#031019;border:1px solid var(--line)"><video id="video" autoplay muted playsinline style="width:100%;display:block;min-height:300px;max-height:520px;object-fit:cover"></video><canvas id="overlay" style="position:absolute;inset:0;width:100%;height:100%;background:transparent;border:0"></canvas></div></div><div class="stack"><div class="kpi"><span>Changed pixels</span><strong id="motion">0.0%</strong></div><div class="panel"><h2>Motion lab</h2><label>Sensitivity (per channel)<input type="range" min="8" max="100" value="36" id="sensitivity"></label><label>Alert threshold %<input type="range" min="1" max="40" value="6" id="threshold"></label><p id="vstatus" class="status">Camera idle</p><p class="hint">Video stays in your browser. Webcam permissions require HTTPS or localhost. No images are uploaded; snapshots download directly to your device.</p></div></div></div>''',
'chain-lab':'''<div class="cols"><div class="panel"><h2>Block constructor</h2><label>Transaction payload<textarea id="payload">Alice -> Bob : 5 educational tokens</textarea></label><label>Mining difficulty (leading zero hex digits)<input id="difficulty" type="range" min="1" max="4" value="2"></label><p id="difficultyText" class="mono">2 zeroes</p><div class="controls"><button id="mine">Mine next block</button><button class="secondary" id="tamper">Tamper previous block</button><button class="secondary" id="verify">Verify chain</button></div><p id="chainStatus" class="status"></p></div><div class="panel"><h2>Chain state</h2><div id="blocks" class="stack"></div></div></div>''',
'threat-lab':'''<div class="stack"><div class="panel"><div class="controls"><button id="sample">Load realistic sample logs</button><label>Load CSV file<input type="file" id="file" accept=".csv,text/plain,.log"></label><label>Window (seconds)<input id="window" type="number" value="90" min="10" max="3600" style="width:110px"></label><label>Failed logins<input id="cutoff" type="number" value="4" min="2" max="30" style="width:90px"></label><button id="analyze">Analyze</button></div><p class="hint">CSV: timestamp,ip,event,user. Rules detect burst failures, failure-to-success escalation, and IP spray across identities. All analysis is local; no malware is generated or executed.</p></div><div class="cols3"><div class="kpi"><span>Events</span><strong id="events">0</strong></div><div class="kpi"><span>Distinct IPs</span><strong id="ips">0</strong></div><div class="kpi"><span>Alerts</span><strong id="alerts">0</strong></div></div><div class="cols"><div class="panel"><h2>Threat findings</h2><div id="findings" class="stack"></div></div><div class="panel"><h2>Event timeline</h2><canvas id="timeline" width="750" height="330"></canvas><p id="logstatus" class="status"></p></div></div></div>''',
'neural-playground':'''<div class="cols"><div class="panel"><div class="controls"><label>Dataset<select id="dataset"><option value="xor">XOR classification</option><option value="circle">Concentric circles</option><option value="spiral">Two spirals</option></select></label><label>Hidden neurons<input type="number" id="neurons" value="12" min="3" max="32" style="width:90px"></label><label>Learning rate<input id="lr" value="0.04" type="number" step="0.01" min="0.001" max="0.8" style="width:90px"></label></div><div class="controls" style="margin:12px 0"><button id="train">Train 150 epochs</button><button id="reset" class="secondary">Reset weights</button></div><canvas id="decision" width="480" height="480"></canvas></div><div class="stack"><div class="cols"><div class="kpi"><span>Epoch</span><strong id="epoch">0</strong></div><div class="kpi"><span>Cross entropy</span><strong id="loss">—</strong></div></div><div class="panel"><h2>Loss history</h2><canvas id="lossCanvas" width="480" height="250"></canvas><p class="hint">Fully connected 2 → hidden tanh → 1 sigmoid network. Backpropagation and SGD implemented without external ML libraries. The purple and green decision boundary changes as weights train.</p></div></div></div>''',
'growth-lab':'''<div class="stack"><div class="panel"><h2>Campaign experiment design</h2><div class="controls"><label>A visitors<input id="na" type="number" value="1500" min="20"></label><label>A conversions<input id="ca" type="number" value="132" min="0"></label><label>B visitors<input id="nb" type="number" value="1500" min="20"></label><label>B conversions<input id="cb" type="number" value="168" min="0"></label><button id="test">Analyze test</button></div><div id="results" class="cols3" style="margin-top:14px"></div></div><div class="cols"><div class="panel"><h2>Bandit strategy simulator</h2><p>Compare epsilon-greedy selection with static equal allocation against three hidden campaign conversion rates.</p><label>Trials<input id="trials" type="range" min="300" max="10000" step="100" value="3000"></label><button id="simulate">Run 3,000 simulated visitors</button><p class="hint">Synthetic seeded trials, educational simulation. It does not connect to marketing ad platforms.</p></div><div class="panel"><canvas id="bandit" width="610" height="335"></canvas><div id="banditStats" class="status"></div></div></div></div>''',
'cloud-lab':'''<div class="stack"><div class="panel"><h2>Resilience architecture workshop</h2><div class="controls"><label>Application replicas<input type="number" id="replicas" value="3" min="1" max="12"></label><label>Replica failure / year (%)<input id="failure" type="number" value="6" min="0" max="90" step=".5"></label><label>Shared database failure (%)<input id="database" type="number" value="2" min="0" max="90" step=".5"></label><label>Simulated minutes<input id="steps" type="number" value="20000" min="100" max="100000"></label><button id="simulate">Run Monte Carlo</button></div><p class="hint">Reliability teaching model, not a production SLO. Failures are independent Bernoulli draws unless a shared dependency is down. Costs are illustrative only, not provider quotes.</p></div><div class="cols3"><div class="kpi"><span>Estimated uptime</span><strong id="uptime">—</strong></div><div class="kpi"><span>Simulated downtime</span><strong id="downtime">—</strong></div><div class="kpi"><span>Monthly compute*</span><strong id="cost">—</strong></div></div><div class="cols"><div class="panel"><h2>Dependency graph</h2><canvas id="graph" width="660" height="360"></canvas></div><div class="panel"><h2>Availability by design</h2><canvas id="bars" width="660" height="360"></canvas></div></div></div>''',
'climate-live':'''<div class="stack"><div class="panel"><h2>Open-Meteo / live public readings</h2><div class="controls"><label>Region<select id="city"><option value="12.9716,77.5946">Bengaluru</option><option value="3.139,101.6869">Kuala Lumpur</option><option value="1.3521,103.8198">Singapore</option><option value="22.5726,88.3639">Kolkata</option><option value="40.7128,-74.006">New York</option></select></label><button id="load">Fetch observations</button></div><p class="hint">Current and hourly conditions returned by Open-Meteo weather and air-quality APIs. Actual availability depends on the public services and your network. Values are not simulated.</p><p id="updated" class="status"></p></div><div class="cols3"><div class="kpi"><span>Temperature</span><strong id="temp">—</strong></div><div class="kpi"><span>Wind</span><strong id="wind">—</strong></div><div class="kpi"><span>PM2.5</span><strong id="pm">—</strong></div></div><div class="panel"><h2>Forecast — next 24 hours</h2><canvas id="forecast" width="1140" height="390"></canvas></div></div>'''
}
for slug,name,cat,desc,icon,theme in CATALOG:
 p=APPS/slug;p.mkdir(exist_ok=True)
 body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(desc,quote=True)}"><link rel="stylesheet" href="../../styles.css"><title>{escape(name)} | SP Advanced Labs</title></head><body class="{theme}"><header class="top"><a class="brand" href="../../">SP / ADVANCED LABS</a><a class="back" href="../../">← All projects</a><span class="tag">{escape(cat)}</span></header><main class="container"><header class="hero"><div><span class="eyebrow">{escape(cat)}</span><h1>{icon} {escape(name)}</h1><p>{escape(desc)}</p></div><span class="tag">Open source · Portfolio engineering</span></header>{BODIES[slug]}</main><footer class="footer">Built for portfolio demonstration · Source available on GitHub · No private data transmitted unless clearly stated</footer><script src="app.js"></script></body></html>'''
 (p/'index.html').write_text(body,encoding='utf8')
 (p/'README.md').write_text(f'# {name}\n\n{desc}\n\nRun locally with a static server: `python -m http.server 8000` from the Advanced Labs root and open `http://localhost:8000/apps/{slug}/`.\n\nNo credential or secret is embedded. See app.js for implementation and edge cases.\n',encoding='utf8')
(ROOT/'catalog.json').write_text(json.dumps([{'slug':s,'name':n,'category':c,'description':d,'icon':i}for s,n,c,d,i,_ in CATALOG],indent=2),encoding='utf8')
items=''.join(f'<a class="tile {theme}" href="apps/{slug}/"><div class="tileIcon">{icon}</div><span class="eyebrow">{escape(cat)}</span><h2>{escape(name)}</h2><p>{escape(desc)}</p><span class="view">Launch project ↗</span></a>'for slug,name,cat,desc,icon,theme in CATALOG)
(ROOT/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advanced Labs · Sharanya Pal</title><meta name="description" content="Real interactive software engineering labs by Sharanya Pal"><link rel="stylesheet" href="styles.css"><style>body{{background:#080c11}}.top{{padding-top:22px;padding-bottom:22px}}.lead{{min-height:340px;display:grid;align-content:center;border-bottom:1px solid #253441}}.lead h1{{font-size:clamp(3rem,8vw,7rem);max-width:990px}}.lead h1 em{{color:#b5ff80;font-style:normal}}.tiles{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:28px}}.tile{{background:linear-gradient(120deg,var(--panel),#10151b);border:1px solid var(--line);padding:23px;border-radius:16px;min-height:260px;display:flex;flex-direction:column;transition:transform .2s,border-color .2s}}.tile:hover{{transform:translateY(-5px);border-color:var(--accent)}}.tileIcon{{font-size:2.5rem;margin-bottom:22px;color:var(--accent)}}.tile h2{{margin:8px 0}}.tile p{{font-size:.84rem}}.tile .view{{margin-top:auto;color:var(--accent);font-size:.82rem;font-weight:700}}@media(max-width:920px){{.tiles{{grid-template-columns:1fr 1fr}}}}@media(max-width:580px){{.tiles{{grid-template-columns:1fr}}}}</style></head><body><header class="top"><a class="brand" href="https://sharanya-pal-cinematic-portfolio.vercel.app">SHARANYA PAL / PORTFOLIO</a><span class="tag">ADVANCED LABS · EDITION 01</span></header><main class="container"><section class="lead"><span class="eyebrow">Algorithms × Experiences</span><h1>Code that <em>does things.</em></h1><p>Ten substantial browser-based systems, built for exploration: decision engines, games, analytics, computer vision, security, distributed-system thinking, and genuine third-party API integration. Not screenshots. Launch the source-backed apps.</p></section><div class="controls" style="margin-top:26px"><input id="search" placeholder="Search by technology, project, concept…" style="width:min(420px,100%)"><span id="count" class="tag">10 projects</span></div><section class="tiles" id="tiles">{items}</section><p style="margin-top:45px">See the source repository for corresponding Python, Java and evaluation test suites. Educational simulation labels are explicit within each project.</p></main><script>const s=document.querySelector('#search');s.addEventListener('input',()=>{{let visible=0;document.querySelectorAll('.tile').forEach(t=>{{let yes=t.textContent.toLowerCase().includes(s.value.toLowerCase());t.hidden=!yes;if(yes)visible++}});document.querySelector('#count').textContent=visible+' projects'}})</script></body></html>''',encoding='utf8')
print('Generated',len(CATALOG),'unique page shells')
